  auto restFrames__ = restFrames ? _fbb.CreateVectorOfStructs<rigExec::fb::Frame>(*restFrames) : 0;
  auto selfD__ = selfD ? _fbb.CreateVectorOfStructs<rigExec::fb::Matrix4d>(*selfD) : 0;
  auto parentDinv__ = parentDinv ? _fbb.CreateVectorOfStructs<rigExec::fb::Matrix4d>(*parentDinv) : 0;
  auto rotOrder__ = rotOrder ? _fbb.CreateVector<uint32_t>(*rotOrder) : 0;
  auto restRoundTrip__ = restRoundTrip ? _fbb.CreateVectorOfStructs<rigExec::fb::Matrix4d>(*restRoundTrip) : 0;
  auto defaultRoundTrip__ = defaultRoundTrip ? _fbb.CreateVectorOfStructs<rigExec::fb::Matrix4d>(*defaultRoundTrip) : 0;
  auto posedAuthored__ = posedAuthored ? _fbb.CreateVector<uint8_t>(*posedAuthored) : 0;
  auto posedAuthoredM__ = posedAuthoredM ? _fbb.CreateVectorOfStructs<rigExec::fb::Matrix4d>(*posedAuthoredM) : 0;
  auto noScaleAvars__ = noScaleAvars ? _fbb.CreateVector<uint8_t>(*noScaleAvars) : 0;
  auto avarConstants__ = avarConstants ? _fbb.CreateVector<double>(*avarConstants) : 0;
  auto rotationSign__ = rotationSign ? _fbb.CreateVector<uint8_t>(*rotationSign) : 0;
  auto posedD__ = posedD ? _fbb.CreateVectorOfStructs<rigExec::fb::Matrix4d>(*posedD) : 0;
  auto parentSpaceM__ = parentSpaceM ? _fbb.CreateVectorOfStructs<rigExec::fb::Matrix4d>(*parentSpaceM) : 0;
  auto parentSpaceAuthored__ = parentSpaceAuthored ? _fbb.CreateVector<uint8_t>(*parentSpaceAuthored) : 0;
