inline ::flatbuffers::Offset<SplineIkRest> CreateSplineIkRestDirect(
    ::flatbuffers::FlatBufferBuilder &_fbb,
    const rigExec::fb::Landmarks *cvs = nullptr,
    const rigExec::fb::Frame *rootControl = nullptr,
    const rigExec::fb::Frame *midControl = nullptr,
    const rigExec::fb::Frame *endControl = nullptr,
    const std::vector<rigExec::fb::Frame> *joints = nullptr,
    const std::vector<double> *segmentLengths = nullptr,
    const rigExec::fb::F64 *restArcLength = nullptr,
    const std::vector<double> *volumeWeights = nullptr) {
  auto joints__ = joints ? _fbb.CreateVectorOfStructs<rigExec::fb::Frame>(*joints) : 0;
  auto segmentLengths__ = segmentLengths ? _fbb.CreateVector<double>(*segmentLengths) : 0;
  auto volumeWeights__ = volumeWeights ? _fbb.CreateVector<double>(*volumeWeights) : 0;
  return rigExec::fb::CreateSplineIkRest(
      _fbb,
      cvs,
      rootControl,
      midControl,
      endControl,
      joints__,
      segmentLengths__,
      restArcLength,
      volumeWeights__);
}

