  uint32_t moverPath() const {
    return GetField<uint32_t>(VT_MOVERPATH, 0);
  }
  bool solverOutput() const {
    return GetField<uint8_t>(VT_SOLVEROUTPUT, 0) != 0;
  }
  const ::flatbuffers::Vector<int32_t> *slots() const {
    return GetPointer<const ::flatbuffers::Vector<int32_t> *>(VT_SLOTS);
  }
  const ::flatbuffers::Vector<const rigExec::fb::IntPair *> *propagate() const {
    return GetPointer<const ::flatbuffers::Vector<const rigExec::fb::IntPair *> *>(VT_PROPAGATE);
  }
