inline ::flatbuffers::Offset<RevisionBinding> CreateRevisionBinding(
    ::flatbuffers::FlatBufferBuilder &_fbb,
    uint32_t moverPath = 0,
    uint32_t target = 0,
    uint32_t transform = 0,
    uint32_t transformSpace = 0,
    ::flatbuffers::Offset<::flatbuffers::Vector<uint32_t>> influences = 0,
    uint32_t weightObject = 0,
    uint32_t base = 0,
    uint32_t topologyCounts = 0,
    uint32_t topologyIndices = 0,
    uint32_t cagePoints = 0,
    uint32_t surfacePoints = 0,
    uint32_t bindCoords = 0,
    uint32_t driverCurvePoints = 0,
    uint32_t driverCurveOrder = 0,
    uint32_t driverCurveKnots = 0,
    int32_t driverTransformCount = 0,
    int32_t driverSpaceCount = 0,
    int32_t driverBaseTransformCount = 0,
    uint32_t driverFrames = 0,
    uint32_t widths = 0,
    ::flatbuffers::Offset<::flatbuffers::Vector<uint32_t>> blendInputs = 0,
    ::flatbuffers::Offset<::flatbuffers::Vector<uint32_t>> blendSampleInputs = 0,
    ::flatbuffers::Offset<::flatbuffers::Vector<::flatbuffers::Offset<rigExec::fb::BlendSampleBindingList>>> blendSamples = 0,
    ::flatbuffers::Offset<::flatbuffers::Vector<uint32_t>> phaseInputs = 0,
    ::flatbuffers::Offset<::flatbuffers::Vector<const rigExec::fb::ReadPhase *>> phases = 0,
    const rigExec::fb::ReadPhase *transformPhase = nullptr) {
  RevisionBindingBuilder builder_(_fbb);
  builder_.add_transformPhase(transformPhase);
  builder_.add_phases(phases);
  builder_.add_phaseInputs(phaseInputs);
  builder_.add_blendSamples(blendSamples);
  builder_.add_blendSampleInputs(blendSampleInputs);
  builder_.add_blendInputs(blendInputs);
  builder_.add_widths(widths);
  builder_.add_driverFrames(driverFrames);
  builder_.add_driverBaseTransformCount(driverBaseTransformCount);
  builder_.add_driverSpaceCount(driverSpaceCount);
  builder_.add_driverTransformCount(driverTransformCount);
  builder_.add_driverCurveKnots(driverCurveKnots);
  builder_.add_driverCurveOrder(driverCurveOrder);
  builder_.add_driverCurvePoints(driverCurvePoints);
  builder_.add_bindCoords(bindCoords);
  builder_.add_surfacePoints(surfacePoints);
  builder_.add_cagePoints(cagePoints);
  builder_.add_topologyIndices(topologyIndices);
  builder_.add_topologyCounts(topologyCounts);
  builder_.add_base(base);
  builder_.add_weightObject(weightObject);
  builder_.add_influences(influences);
  builder_.add_transformSpace(transformSpace);
  builder_.add_transform(transform);
  builder_.add_target(target);
  builder_.add_moverPath(moverPath);
  return builder_.Finish();
}

struct RevisionBinding::Traits {
  using type = RevisionBinding;
  static auto constexpr Create = CreateRevisionBinding;
};

inline ::flatbuffers::Offset<RevisionBinding> CreateRevisionBindingDirect(
    ::flatbuffers::FlatBufferBuilder &_fbb,
    uint32_t moverPath = 0,
    uint32_t target = 0,
    uint32_t transform = 0,
    uint32_t transformSpace = 0,
    const std::vector<uint32_t> *influences = nullptr,
    uint32_t weightObject = 0,
    uint32_t base = 0,
    uint32_t topologyCounts = 0,
    uint32_t topologyIndices = 0,
    uint32_t cagePoints = 0,
    uint32_t surfacePoints = 0,
    uint32_t bindCoords = 0,
    uint32_t driverCurvePoints = 0,
    uint32_t driverCurveOrder = 0,
    uint32_t driverCurveKnots = 0,
    int32_t driverTransformCount = 0,
    int32_t driverSpaceCount = 0,
    int32_t driverBaseTransformCount = 0,
    uint32_t driverFrames = 0,
    uint32_t widths = 0,
    const std::vector<uint32_t> *blendInputs = nullptr,
    const std::vector<uint32_t> *blendSampleInputs = nullptr,
    const std::vector<::flatbuffers::Offset<rigExec::fb::BlendSampleBindingList>> *blendSamples = nullptr,
    const std::vector<uint32_t> *phaseInputs = nullptr,
    const std::vector<rigExec::fb::ReadPhase> *phases = nullptr,
    const rigExec::fb::ReadPhase *transformPhase = nullptr) {
  auto influences__ = influences ? _fbb.CreateVector<uint32_t>(*influences) : 0;
  auto blendInputs__ = blendInputs ? _fbb.CreateVector<uint32_t>(*blendInputs) : 0;
  auto blendSampleInputs__ = blendSampleInputs ? _fbb.CreateVector<uint32_t>(*blendSampleInputs) : 0;
  auto blendSamples__ = blendSamples ? _fbb.CreateVector<::flatbuffers::Offset<rigExec::fb::BlendSampleBindingList>>(*blendSamples) : 0;
  auto phaseInputs__ = phaseInputs ? _fbb.CreateVector<uint32_t>(*phaseInputs) : 0;
  auto phases__ = phases ? _fbb.CreateVectorOfStructs<rigExec::fb::ReadPhase>(*phases) : 0;
  return rigExec::fb::CreateRevisionBinding(
      _fbb,
      moverPath,
      target,
      transform,
      transformSpace,
      influences__,
      weightObject,
      base,
      topologyCounts,
      topologyIndices,
      cagePoints,
      surfacePoints,
      bindCoords,
      driverCurvePoints,
      driverCurveOrder,
      driverCurveKnots,
      driverTransformCount,
      driverSpaceCount,
      driverBaseTransformCount,
      driverFrames,
      widths,
      blendInputs__,
      blendSampleInputs__,
      blendSamples__,
      phaseInputs__,
      phases__,
      transformPhase);
}

