inline ::flatbuffers::Offset<DomainGeometry> CreateDomainGeometry(
    ::flatbuffers::FlatBufferBuilder &_fbb,
    ::flatbuffers::Offset<::flatbuffers::Vector<::flatbuffers::Offset<rigExec::fb::Chain>>> chains = 0,
    ::flatbuffers::Offset<::flatbuffers::Vector<const rigExec::fb::IntPair *>> revisionIndex = 0,
    ::flatbuffers::Offset<::flatbuffers::Vector<const rigExec::fb::IntPair *>> derivedIndex = 0,
    ::flatbuffers::Offset<::flatbuffers::Vector<int32_t>> chainRevisionBegin = 0,
    ::flatbuffers::Offset<::flatbuffers::Vector<int32_t>> chainRevisionEnd = 0,
    ::flatbuffers::Offset<::flatbuffers::Vector<int32_t>> revisionChunkBase = 0,
    ::flatbuffers::Offset<::flatbuffers::Vector<int32_t>> revisionChunkCount = 0,
    ::flatbuffers::Offset<::flatbuffers::Vector<int32_t>> chainChunkBegin = 0,
    ::flatbuffers::Offset<::flatbuffers::Vector<int32_t>> chainChunkEnd = 0,
    ::flatbuffers::Offset<::flatbuffers::Vector<::flatbuffers::Offset<rigExec::fb::WeightObject>>> weightObjects = 0,
    ::flatbuffers::Offset<::flatbuffers::Vector<uint32_t>> falloffPaths = 0,
    ::flatbuffers::Offset<::flatbuffers::Vector<::flatbuffers::Offset<rigExec::fb::FloatList>>> falloffLuts = 0,
    ::flatbuffers::Offset<::flatbuffers::Vector<uint32_t>> currentPhaseWeights = 0,
    ::flatbuffers::Offset<::flatbuffers::Vector<uint32_t>> deltaBasePaths = 0,
    ::flatbuffers::Offset<::flatbuffers::Vector<const rigExec::fb::Matrix4d *>> deltaBaseMatrix = 0,
    ::flatbuffers::Offset<::flatbuffers::Vector<uint8_t>> deltaBaseOk = 0,
    ::flatbuffers::Offset<::flatbuffers::Vector<::flatbuffers::Offset<rigExec::fb::PathRead>>> pathReads = 0,
    ::flatbuffers::Offset<::flatbuffers::Vector<::flatbuffers::Offset<rigExec::fb::WeightField>>> weightFields = 0) {
  DomainGeometryBuilder builder_(_fbb);
  builder_.add_weightFields(weightFields);
  builder_.add_pathReads(pathReads);
  builder_.add_deltaBaseOk(deltaBaseOk);
  builder_.add_deltaBaseMatrix(deltaBaseMatrix);
  builder_.add_deltaBasePaths(deltaBasePaths);
  builder_.add_currentPhaseWeights(currentPhaseWeights);
  builder_.add_falloffLuts(falloffLuts);
  builder_.add_falloffPaths(falloffPaths);
  builder_.add_weightObjects(weightObjects);
  builder_.add_chainChunkEnd(chainChunkEnd);
  builder_.add_chainChunkBegin(chainChunkBegin);
  builder_.add_revisionChunkCount(revisionChunkCount);
  builder_.add_revisionChunkBase(revisionChunkBase);
  builder_.add_chainRevisionEnd(chainRevisionEnd);
  builder_.add_chainRevisionBegin(chainRevisionBegin);
  builder_.add_derivedIndex(derivedIndex);
  builder_.add_revisionIndex(revisionIndex);
  builder_.add_chains(chains);
  return builder_.Finish();
}

