inline ::flatbuffers::Offset<DomainGeometry> CreateDomainGeometryDirect(
    ::flatbuffers::FlatBufferBuilder &_fbb,
    const std::vector<::flatbuffers::Offset<rigExec::fb::Chain>> *chains = nullptr,
    const std::vector<rigExec::fb::IntPair> *revisionIndex = nullptr,
    const std::vector<rigExec::fb::IntPair> *derivedIndex = nullptr,
    const std::vector<int32_t> *chainRevisionBegin = nullptr,
    const std::vector<int32_t> *chainRevisionEnd = nullptr,
    const std::vector<int32_t> *revisionChunkBase = nullptr,
    const std::vector<int32_t> *revisionChunkCount = nullptr,
    const std::vector<int32_t> *chainChunkBegin = nullptr,
    const std::vector<int32_t> *chainChunkEnd = nullptr,
    const std::vector<::flatbuffers::Offset<rigExec::fb::WeightObject>> *weightObjects = nullptr,
    const std::vector<uint32_t> *falloffPaths = nullptr,
    const std::vector<::flatbuffers::Offset<rigExec::fb::FloatList>> *falloffLuts = nullptr,
    const std::vector<uint32_t> *currentPhaseWeights = nullptr,
    const std::vector<uint32_t> *deltaBasePaths = nullptr,
    const std::vector<rigExec::fb::Matrix4d> *deltaBaseMatrix = nullptr,
    const std::vector<uint8_t> *deltaBaseOk = nullptr,
    const std::vector<::flatbuffers::Offset<rigExec::fb::PathRead>> *pathReads = nullptr,
    const std::vector<::flatbuffers::Offset<rigExec::fb::WeightField>> *weightFields = nullptr) {
  auto chains__ = chains ? _fbb.CreateVector<::flatbuffers::Offset<rigExec::fb::Chain>>(*chains) : 0;
  auto revisionIndex__ = revisionIndex ? _fbb.CreateVectorOfStructs<rigExec::fb::IntPair>(*revisionIndex) : 0;
  auto derivedIndex__ = derivedIndex ? _fbb.CreateVectorOfStructs<rigExec::fb::IntPair>(*derivedIndex) : 0;
  auto chainRevisionBegin__ = chainRevisionBegin ? _fbb.CreateVector<int32_t>(*chainRevisionBegin) : 0;
  auto chainRevisionEnd__ = chainRevisionEnd ? _fbb.CreateVector<int32_t>(*chainRevisionEnd) : 0;
  auto revisionChunkBase__ = revisionChunkBase ? _fbb.CreateVector<int32_t>(*revisionChunkBase) : 0;
  auto revisionChunkCount__ = revisionChunkCount ? _fbb.CreateVector<int32_t>(*revisionChunkCount) : 0;
  auto chainChunkBegin__ = chainChunkBegin ? _fbb.CreateVector<int32_t>(*chainChunkBegin) : 0;
  auto chainChunkEnd__ = chainChunkEnd ? _fbb.CreateVector<int32_t>(*chainChunkEnd) : 0;
  auto weightObjects__ = weightObjects ? _fbb.CreateVector<::flatbuffers::Offset<rigExec::fb::WeightObject>>(*weightObjects) : 0;
  auto falloffPaths__ = falloffPaths ? _fbb.CreateVector<uint32_t>(*falloffPaths) : 0;
  auto falloffLuts__ = falloffLuts ? _fbb.CreateVector<::flatbuffers::Offset<rigExec::fb::FloatList>>(*falloffLuts) : 0;
  auto currentPhaseWeights__ = currentPhaseWeights ? _fbb.CreateVector<uint32_t>(*currentPhaseWeights) : 0;
  auto deltaBasePaths__ = deltaBasePaths ? _fbb.CreateVector<uint32_t>(*deltaBasePaths) : 0;
  auto deltaBaseMatrix__ = deltaBaseMatrix ? _fbb.CreateVectorOfStructs<rigExec::fb::Matrix4d>(*deltaBaseMatrix) : 0;
  auto deltaBaseOk__ = deltaBaseOk ? _fbb.CreateVector<uint8_t>(*deltaBaseOk) : 0;
  auto pathReads__ = pathReads ? _fbb.CreateVector<::flatbuffers::Offset<rigExec::fb::PathRead>>(*pathReads) : 0;
  auto weightFields__ = weightFields ? _fbb.CreateVector<::flatbuffers::Offset<rigExec::fb::WeightField>>(*weightFields) : 0;
  return rigExec::fb::CreateDomainGeometry(
      _fbb,
      chains__,
      revisionIndex__,
      derivedIndex__,
      chainRevisionBegin__,
      chainRevisionEnd__,
      revisionChunkBase__,
      revisionChunkCount__,
      chainChunkBegin__,
      chainChunkEnd__,
      weightObjects__,
      falloffPaths__,
      falloffLuts__,
      currentPhaseWeights__,
      deltaBasePaths__,
      deltaBaseMatrix__,
      deltaBaseOk__,
      pathReads__,
      weightFields__);
}

