inline const rigExec::fb::File *GetFile(const void *buf) {
  return ::flatbuffers::GetRoot<rigExec::fb::File>(buf);
}

inline const rigExec::fb::File *GetSizePrefixedFile(const void *buf) {
  return ::flatbuffers::GetSizePrefixedRoot<rigExec::fb::File>(buf);
}

inline const char *FileIdentifier() {
  return "REXB";
}

inline bool FileBufferHasIdentifier(const void *buf) {
  return ::flatbuffers::BufferHasIdentifier(
      buf, FileIdentifier());
}

inline bool SizePrefixedFileBufferHasIdentifier(const void *buf) {
  return ::flatbuffers::BufferHasIdentifier(
      buf, FileIdentifier(), true);
}

template <bool B = false>
inline bool VerifyFileBuffer(
    ::flatbuffers::VerifierTemplate<B> &verifier) {
  return verifier.template VerifyBuffer<rigExec::fb::File>(FileIdentifier());
}

template <bool B = false>
inline bool VerifySizePrefixedFileBuffer(
    ::flatbuffers::VerifierTemplate<B> &verifier) {
  return verifier.template VerifySizePrefixedBuffer<rigExec::fb::File>(FileIdentifier());
}

inline const char *FileExtension() {
  return "rigexec";
}

inline void FinishFileBuffer(
    ::flatbuffers::FlatBufferBuilder &fbb,
    ::flatbuffers::Offset<rigExec::fb::File> root) {
  fbb.Finish(root, FileIdentifier());
}

inline void FinishSizePrefixedFileBuffer(
    ::flatbuffers::FlatBufferBuilder &fbb,
    ::flatbuffers::Offset<rigExec::fb::File> root) {
  fbb.FinishSizePrefixed(root, FileIdentifier());
}

inline std::unique_ptr<rigExec::fb::RigExecWireFile> UnPackFile(
    const void *buf,
    const ::flatbuffers::resolver_function_t *res = nullptr) {
  return std::unique_ptr<rigExec::fb::RigExecWireFile>(GetFile(buf)->UnPack(res));
}

inline std::unique_ptr<rigExec::fb::RigExecWireFile> UnPackSizePrefixedFile(
    const void *buf,
    const ::flatbuffers::resolver_function_t *res = nullptr) {
  return std::unique_ptr<rigExec::fb::RigExecWireFile>(GetSizePrefixedFile(buf)->UnPack(res));
}

